"""Parity of the PyTorch implementation with reference values generated by the TensorFlow implementation
(see tests/tools/gen_tf_reference.py)."""
import glob
import os

import numpy as np
import pytest
import torch

from pyace.basis import BBasisConfiguration

from torchpotential.constants import *
from torchpotential.indexing import Batch
from torchpotential.potentials.ace import ACE
from torchpotential.torchpot import TorchPotential

HERE = os.path.dirname(os.path.abspath(__file__))
REF_FILES = sorted(glob.glob(os.path.join(HERE, "data", "tf_ref", "*.npz")))
BATCH_KEYS = ["positions", "offsets", "cell", "energy", "forces", "eweights", "fweights", "ind_i", "ind_j", "mu_i",
              "mu_j", "pair_map", "cell_map", "e_map"]

YAML_OF_CASE = {
    "unary_r1234": "Al-r1234l12_crad_dif_2.yaml",
    "binary_AlNi": "Al-Ni_opt_all.yaml",
    "ternary_AlCuZn": "ternary_AlCuZn.yaml",
    "unary_lmax6_cu": "Cu.pbe.in.yaml",
    "unary_sbessel_rank1": "SBessel_rank1.yaml",
    "unary_2dens_ni": "Ni_2dens_bug_case.yaml",
}


def close(a, b, rtol=1e-11):
    a, b = np.asarray(a), np.asarray(b)
    scale = max(np.max(np.abs(b)), 1e-300)
    np.testing.assert_allclose(a, b, rtol=rtol, atol=rtol * scale)


def load(path):
    ref = np.load(path, allow_pickle=False)
    case = os.path.basename(path).split("__")[0]
    bconf = BBasisConfiguration(os.path.join(HERE, "data", "yaml", YAML_OF_CASE[case]))
    # the TF implementation never applied the core repulsion (its inner cutoff is 0 by default), so the references
    # contain none: switch it off to compare like with like (see test_core_repulsion.py for the C++-conform term)
    for blk in bconf.funcspecs_blocks:
        blk.core_rep_parameters = [0.0, 1.0]
    has_aux = bool(ref["has_aux"])
    ace = ACE(bconf, compute_orthogonality=has_aux, compute_smoothness=has_aux)
    ace.set_coefs(ref["coefs"])
    specs = {LOSS_TYPE: str(ref["loss_type"]), LOSS_FORCE_FACTOR: float(ref["kappa"]),
             LOSS_ENERGY_FACTOR: 1 - float(ref["kappa"]), L1_REG: float(ref["L1"]), L2_REG: float(ref["L2"])}
    if has_aux:
        specs[AUX_LOSS_FACTOR] = list(ref["aux_factors"])
    tp = TorchPotential(ace, loss_specs=specs)
    batch = {k: ref["in_" + k] for k in BATCH_KEYS}
    return ref, ace, tp, batch


@pytest.mark.parametrize("path", REF_FILES, ids=[os.path.basename(p)[:-4] for p in REF_FILES])
def test_loss_grad_energy_forces(path):
    ref, ace, tp, batch = load(path)
    loss, grad, e, f = tp.external_fit(ref["coefs"], batch)
    close(e.cpu().numpy(), ref["e"])
    close(f.cpu().numpy(), ref["f"])
    close(loss.cpu().numpy(), ref["loss"])
    close(grad.cpu().numpy(), ref["grad"])
    close(tp.reg_components.cpu().numpy().reshape(-1), np.asarray(ref["reg_components"]).reshape(-1))


@pytest.mark.parametrize("path", REF_FILES, ids=[os.path.basename(p)[:-4] for p in REF_FILES])
def test_evaluate_energy_forces_stress(path):
    ref, ace, tp, batch = load(path)
    ace.set_coefs(ref["coefs"])
    e, f, s = tp.evaluate(batch)
    close(e.cpu().numpy(), ref["e_eval"])
    close(f.cpu().numpy(), ref["f_eval"])
    close(s.cpu().numpy(), ref["s_eval"])


@pytest.mark.parametrize("path", [p for p in REF_FILES if "hess" in np.load(p).files],
                         ids=lambda p: os.path.basename(p)[:-4])
def test_hessian(path):
    ref, ace, tp, batch = load(path)
    small = {k: ref["hin_" + k] for k in BATCH_KEYS}
    e, hess = tp.evaluate_hessian(small)
    close(e.cpu().numpy(), ref["hess_e"])
    close(hess.cpu().numpy(), ref["hess"], rtol=1e-8)


@pytest.mark.parametrize("path", REF_FILES, ids=[os.path.basename(p)[:-4] for p in REF_FILES])
def test_updated_config_roundtrip(path):
    ref, ace, tp, batch = load(path)
    conf = ace.get_updated_config(updating_coefs=ref["coefs"])
    ref_conf = BBasisConfiguration(os.path.join(HERE, "data", "yaml", str(ref["updated_yaml"])))
    close(conf.get_all_coeffs(), ref_conf.get_all_coeffs(), rtol=1e-12)
